mapper.select:
SELECT
    (SELECT COALESCE(SUM(e.amount), 0) FROM biz_expense e
        WHERE e.deleted = 0
        AND e.expense_date >= #{begin}
        AND e.expense_date <= #{end}
    ) AS totalCost,
    (SELECT COALESCE(SUM(o.total_amount), 0) FROM biz_outbound o
        WHERE o.deleted = 0 AND o.status = 1
        AND o.outbound_date >= #{begin}
        AND o.outbound_date <= #{end}
    ) AS totalOutput
